"""Payment provider webhooks."""

from fastapi import APIRouter
from pydantic import BaseModel
from pymongo.errors import DuplicateKeyError

from . import ledger
from .db import get_db

router = APIRouter()


class ProviderEvent(BaseModel):
    id: str
    customer_id: str
    amount: int


@router.post("/webhooks/provider")
def receive(event: ProviderEvent) -> dict:
    # The payments collection holds one record per customer (unique index on
    # customer_id), so update that record instead of inserting a new one.
    # The filter excludes records that already applied this event id; in that
    # case the upsert collides with the unique index and we treat it as a replay.
    try:
        get_db().payments.update_one(
            {
                "customer_id": event.customer_id,
                "provider_event_ids": {"$ne": event.id},
            },
            {
                "$set": {"provider_event_id": event.id},
                "$addToSet": {"provider_event_ids": event.id},
                "$inc": {"amount": event.amount},
            },
            upsert=True,
        )
    except DuplicateKeyError:
        return {"ok": True, "duplicate": True}
    ledger.credit(event.customer_id, event.amount, event.id)
    return {"ok": True}

