    db = get_db()

    # Per-event record, deduplicated by provider event id (idempotent redelivery).
    db.payment_events.create_index("provider_event_id", unique=True)
    try:
        db.payment_events.insert_one(
            {
                "provider_event_id": event.id,
                "customer_id": event.customer_id,
                "amount": event.amount,
            }
        )
    except DuplicateKeyError:
        return {"ok": True, "duplicate": True}

    # payments keeps one document per customer (unique customer_id index),
    # so update the existing one rather than inserting another.
    db.payments.update_one(
        {"customer_id": event.customer_id},
        {
            "$set": {"provider_event_id": event.id},
            "$inc": {"amount": event.amount},
        },
        upsert=True,
    )
    ledger.credit(event.customer_id, event.amount, event.id)
