from fastapi import APIRouter
from pydantic import BaseModel
from pymongo.errors import DuplicateKeyError

from . import ledger
from .db import get_db

router = APIRouter()


class ProviderEvent(BaseModel):
    id: str
    customer_id: str
    amount: int


@router.post("/webhooks/provider")
def receive(event: ProviderEvent) -> dict:
    db = get_db()

    # Idempotency: claim the event id (the _id is unique). A provider retry of
    # the same event is acknowledged without crediting twice.
    try:
        db.payment_events.insert_one(
            {
                "_id": event.id,
                "provider_event_id": event.id,
                "customer_id": event.customer_id,
                "amount": event.amount,
            }
        )
    except DuplicateKeyError:
        return {"ok": True, "duplicate": True}

    try:
        # payments keeps one row per customer (unique index on customer_id);
        # accumulate further events into it instead of inserting a new row.
        db.payments.update_one(
            {"customer_id": event.customer_id},
            {
                "$setOnInsert": {
                    "customer_id": event.customer_id,
                    "provider_event_id": event.id,
                },
                "$inc": {"amount": event.amount},
                "$push": {"provider_event_ids": event.id},
            },
            upsert=True,
        )
        ledger.credit(event.customer_id, event.amount, event.id)
    except Exception:
        # Release the claim so the provider's retry can be processed.
        db.payment_events.delete_one({"_id": event.id})
        raise
    return {"ok": True}

