from fastapi import APIRouter
from pydantic import BaseModel

from . import ledger
from .db import get_db

router = APIRouter()


class ProviderEvent(BaseModel):
    id: str
    customer_id: str
    amount: int


@router.post("/webhooks/provider")
def receive(event: ProviderEvent) -> dict:
    db = get_db()

    # Provider retries the same event id: don't credit twice.
    if db.ledger.find_one({"event_id": event.id}) is not None:
        return {"ok": True, "duplicate": True}

    # payments holds one row per customer (unique index on customer_id), so
    # a customer's later events must not insert another row.
    db.payments.update_one(
        {"customer_id": event.customer_id},
        {
            "$setOnInsert": {
                "provider_event_id": event.id,
                "customer_id": event.customer_id,
                "amount": event.amount,
            }
        },
        upsert=True,
    )
    ledger.credit(event.customer_id, event.amount, event.id)
    return {"ok": True}
